<section class="section"><h2>🚚 Real-Time Tracking</h2><div class="tracking-box"><h3>📦 Order Confirmation</h3><p>After placing your order, your order ID and status are available from the order system.</p><?php if(isset($_SESSION['user_id'])): ?><a class="btn-primary" href="tracking.php?view=1">View My Orders</a><?php endif; ?></div><?php if(isset($_SESSION['user_id']) && isset($_GET['view'])): ?><?php include __DIR__.'/includes/db.php'; $uid=(int)$_SESSION['user_id'];$st=mysqli_prepare($conn,"SELECT id,total_amount,status,payment_method,created_at FROM orders WHERE user_id=? ORDER BY id DESC");mysqli_stmt_bind_param($st,'i',$uid);mysqli_stmt_execute($st);$r=mysqli_stmt_get_result($st); ?><div class="tracking-box"><h3>My Orders</h3><?php while($o=mysqli_fetch_assoc($r)): ?><p><b>Order #<?php echo $o['id']; ?></b> — ৳<?php echo number_format($o['total_amount'],2); ?> — <span class="status-badge status-<?php echo htmlspecialchars($o['status']); ?>"><?php echo htmlspecialchars($o['status']); ?></span> — <?php echo htmlspecialchars($o['created_at']); ?></p><?php endwhile; ?></div><?php endif; ?><div class="tracking-box"><h3>⏱ Delivery Time</h3><input type="range" min="5" max="1440" value="60" id="timeRange"><p id="timeDisplay">Delivery Time: 60 minutes</p></div><div class="tracking-box"><h3>🔔 Low Stock Alert</h3><p>Low stock alerts are generated for administrators when stock becomes 5 or less.</p></div></section><script src="js/tracking.js"></script>
